SET LOCAL aidash.scope = 'deployment';
UPDATE "authorization_bundles" SET "document" = (replace(replace(replace(replace(replace(replace(replace(replace(document::text, '"thread.create"', '"workspace.create"'), '"thread.events"', '"workspace.events"'), '"thread.read"', '"workspace.read"'), '"thread.share"', '"workspace.share"'), '"thread.update"', '"workspace.update"'), '"thread_id"', '"workspace_id"'), '"/thread_id"', '"/workspace_id"'), '"thread"', '"workspace"'))::jsonb, "revision" = "revision" + 1, "updated_at" = CURRENT_TIMESTAMP WHERE (document::text LIKE '%"thread.create"%' OR document::text LIKE '%"thread.events"%' OR document::text LIKE '%"thread.read"%' OR document::text LIKE '%"thread.share"%' OR document::text LIKE '%"thread.update"%' OR document::text LIKE '%"thread_id"%' OR document::text LIKE '%"/thread_id"%' OR document::text LIKE '%"thread"%');
